/* ❌ OLD: The inner grid re-declares its own track sizes instead of
   inheriting the parent's. If the parent changes (e.g. 4 cols -> 6),
   the inner 2-col assumption breaks and columns stop aligning. */

.grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
}

.card {
  grid-column: span 2;
}

.card__body {
  display: grid;
  grid-template-columns: 1fr 1fr; /* ❌ OLD: hard-coded — may not match parent */
}

/* The inner label/value pairs only accidentally align with the outer
   columns; any change to one layout silently misaligns the other. */

/* ✅ NEW: grid-template-columns: subgrid makes the inner grid use the
   parent's exact track list, so inner items align perfectly with the
   outer columns — and stay aligned when the parent changes. */

.grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
}

.card {
  grid-column: span 2;
  display: grid;
  grid-template-columns: subgrid; /* ✅ NEW: inherit the 4 parent columns */
}

/* Inner items now sit on the same vertical lines as outer siblings.
   Track sizing folds nested content into the shared tracks, so an
   auto-sized row grows to fit the card body while keeping alignment. */
